components.css:
.ds-primary-button { display: inline-flex; align-items: center; justify-content: center; gap: 1rem; border: 1px solid transparent; border-radius: 0; padding: .7rem 1rem; min-height: 2.8rem; font-size: .89rem; font-weight: 550; line-height: 1.2; text-decoration: none; font-family: var(--sans, "Helvetica Neue", Helvetica, Arial, sans-serif); cursor: pointer; color: white; background: var(--wine, #911a46); }
.ds-primary-button:hover { background: var(--wine-dark, #701334); }
.ds-primary-button:focus-visible { outline: 2px solid var(--wine, #911a46); outline-offset: 4px; }
.ds-primary-button:disabled { cursor: default; color: var(--muted, #525e65); border-color: var(--line, #c6ccce); background: var(--mist, #e9edef); }
.ds-arrow { width: 1.12rem; height: 1.12rem; flex: none; fill: none; stroke: currentColor; stroke-width: 1.45; }
.ds-primary-button .ds-arrow { transition: transform 160ms ease-out; }
.ds-primary-button:hover .ds-arrow, .ds-primary-button:focus-visible .ds-arrow { transform: translateX(2px); }
@media (prefers-reduced-motion: reduce) { .ds-primary-button .ds-arrow { transition-duration: 0s; } }

.ds-secondary-button { display: inline-flex; align-items: center; justify-content: center; gap: 1rem; border: 1px solid transparent; border-radius: 0; padding: .7rem 1rem; min-height: 2.8rem; font-size: .89rem; font-weight: 550; line-height: 1.2; text-decoration: none; font-family: var(--sans, "Helvetica Neue", Helvetica, Arial, sans-serif); cursor: pointer; color: var(--ink, #262933); border-color: var(--line, #c6ccce); background: var(--white, #fff); }
.ds-secondary-button:hover { background: var(--mist, #e9edef); }
.ds-secondary-button:focus-visible { outline: 2px solid var(--wine, #911a46); outline-offset: 4px; }
.ds-secondary-button:disabled { cursor: default; color: var(--muted, #525e65); border-color: var(--line, #c6ccce); background: var(--mist, #e9edef); }

.ds-text-button { display: inline-flex; align-items: center; justify-content: center; gap: 1rem; border: 1px solid transparent; border-radius: 0; padding: .7rem 1rem; min-height: 2.8rem; font-size: .89rem; font-weight: 550; line-height: 1.2; text-decoration: none; font-family: var(--sans, "Helvetica Neue", Helvetica, Arial, sans-serif); cursor: pointer; color: var(--wine, #911a46); background: transparent; border-color: currentColor; }
.ds-text-button:hover { background: var(--rose, #f7e9ed); }
.ds-text-button:focus-visible { outline: 2px solid var(--wine, #911a46); outline-offset: 4px; }
.ds-text-button:disabled { cursor: default; color: var(--muted, #525e65); border-color: var(--line, #c6ccce); background: var(--mist, #e9edef); }
.ds-arrow { width: 1.12rem; height: 1.12rem; flex: none; fill: none; stroke: currentColor; stroke-width: 1.45; }

.ds-header-help { display: inline-flex; align-items: center; min-height: 2.75rem; padding-block: .25rem; font: .83rem/1.5 var(--sans, "Helvetica Neue", Helvetica, Arial, sans-serif); color: var(--muted, #525e65); text-decoration: none; }
.ds-header-help:hover { color: var(--wine, #911a46); text-decoration: underline; }
.ds-header-help:focus-visible { outline: 2px solid var(--wine, #911a46); outline-offset: 4px; }

.ds-option { display: grid; grid-template-columns: 2rem minmax(0, 1fr); gap: .85rem; align-items: baseline; padding: .9rem .7rem; border-top: 1px solid var(--line, #c6ccce); cursor: pointer; position: relative; font-family: var(--sans, "Helvetica Neue", Helvetica, Arial, sans-serif); font-size: 1rem; line-height: 1.5; color: var(--ink, #262933); }
.ds-option:last-child { border-bottom: 1px solid var(--line, #c6ccce); }
.ds-option:hover { background: var(--mist, #e9edef); }
.ds-option input { width: 1px; height: 1px; opacity: 0; position: absolute; }
.ds-letter { display: grid; place-items: center; align-self: start; width: 1.8rem; height: 1.8rem; border: 1px solid #859197; font-size: .88rem; }
.ds-option:has(:checked) { background: var(--rose, #f7e9ed); }
.ds-option input:checked + .ds-letter { color: white; background: var(--wine, #911a46); border-color: var(--wine, #911a46); }
.ds-option:has(:focus-visible) { outline: 2px solid var(--wine, #911a46); outline-offset: -2px; }
@media (forced-colors: active) { .ds-option input:checked + .ds-letter { outline: 2px solid Highlight; } }

.ds-map { display: grid; grid-template-columns: repeat(auto-fill,minmax(2.75rem,1fr)); gap: .25rem; padding: .375rem; max-height: min(45vh, 25rem); overflow: auto; scrollbar-color: var(--muted, #525e65) var(--mist, #e9edef); font-family: var(--sans, "Helvetica Neue", Helvetica, Arial, sans-serif); max-width: 8rem; }
.ds-cell { display: grid; place-items: center; min-height: 2.75rem; font-size: .79rem; text-decoration: none; background: var(--white, #fff); border: 1px solid var(--line, #c6ccce); color: var(--ink, #262933); font-variant-numeric: tabular-nums; }
.ds-answered { background: var(--mist, #e9edef); border-color: #839398; font-weight: 700; }
.ds-current, .ds-cell:hover { border-color: var(--wine, #911a46); color: var(--wine, #911a46); }
.ds-current { background: var(--rose, #f7e9ed); font-weight: 700; box-shadow: inset 0 0 0 1px var(--wine, #911a46); }
.ds-cell:focus-visible { outline: 2px solid var(--wine, #911a46); outline-offset: 2px; }
@media (forced-colors: active) { .ds-current { outline: 2px solid Highlight; } }

.ds-file { margin-top: .55rem; font-size: .8rem; font-family: var(--sans, "Helvetica Neue", Helvetica, Arial, sans-serif); color: var(--ink, #262933); line-height: 1.5; }
.ds-file summary { width: fit-content; color: var(--ink, #262933); min-height: 2.75rem; padding-block: .65rem; cursor: pointer; }
.ds-file summary:hover { color: var(--wine, #911a46); }
.ds-file summary:focus-visible { outline: 2px solid var(--wine, #911a46); outline-offset: 4px; }
.ds-filename { color: var(--muted, #525e65); margin-left: .45rem; overflow-wrap: anywhere; font-family: ui-monospace, monospace; font-size: .76rem; }
.ds-file dl { margin: .4rem 0 0; }
.ds-file dl div { display: grid; grid-template-columns: 6rem minmax(0,1fr); gap: .45rem; padding-block: .3rem; }
.ds-file dt { color: var(--muted, #525e65); }
.ds-file dd { margin: 0; }
@media (max-width: 44rem) { .ds-filename { display: block; margin: .2rem 0 0 1rem; } .ds-file dl div { grid-template-columns: minmax(0,1fr); gap: .1rem; padding-block: .45rem; } }

.ds-panel { display: flex; flex-wrap: wrap; align-items: baseline; gap: 1rem 2rem; padding: 1.4rem; background: var(--mist, #e9edef); font-family: var(--sans, "Helvetica Neue", Helvetica, Arial, sans-serif); line-height: 1.5; color: var(--ink, #262933); }
.ds-panel > div:first-child { display: grid; gap: .3rem; }
.ds-panel span, .ds-panel small { font-size: .86rem; }
.ds-panel strong { font: 400 2.1rem/1.1 var(--serif, Baskervville, Georgia, serif); }
.ds-panel p { flex: 1 1 25rem; max-width: 70ch; color: var(--muted, #525e65); margin: 0; }

.ds-score-explanation { border-top: 1px solid var(--line, #c6ccce); font: 1rem/1.5 var(--sans, "Helvetica Neue", Helvetica, Arial, sans-serif); }
.ds-score-explanation summary { min-height: 2.75rem; padding-block: .65rem; font-size: .9rem; color: var(--ink, #262933); cursor: pointer; }
.ds-score-explanation summary:hover { color: var(--wine, #911a46); }
.ds-score-explanation summary:focus-visible { outline: 2px solid var(--wine, #911a46); outline-offset: 4px; }
.ds-score-explanation p { max-width: 70ch; margin: .6rem 0 0; color: var(--muted, #525e65); }
